var MISSIONS=[
 {id:'m1',name:'Mission 1: First criticality',brief:'The reactor is shut down at hot zero power (292 °C) with a fresh core and 1200 ppm boron. Withdraw the shutdown banks, then approach criticality with the control bank, using the 1/M plot to predict where it will go critical. Avoid a reactor trip.',
  tips:['Withdraw the shutdown banks first. Count rate rises a little.','Record a 1/M point at 0% control bank, then withdraw in steps (e.g. 10%), waiting for the count rate to settle before each new point. Use 10× speed while waiting.','When 1/M is small, use 1% steps. Once critical, stop withdrawing: the startup rate should sit between 0.2 and 1 DPM.'],
  init:function(){return simNew({n:5e-10,sd:0,cb:0,load:0,rex:BOL,B:1200,Tav:292.25})},failOnTrip:true,
  goals:[['Withdraw the shutdown banks fully',function(s){return s.sd>=0.999}],['Record at least three 1/M points',function(){return SIM.oneM.length>=3}],['Go critical: with the rods stopped, hold a startup rate of 0.2–1.0 DPM for 15 seconds',function(s,dt,m){m.t=(s.sur>=0.2&&s.sur<=1&&s.rho&&s.rho.tot>0&&simStill(s))?(m.t||0)+dt:0;return m.t>=15}]]},
 {id:'m2',name:'Mission 2: Raise power to 30%',brief:'The reactor is critical at about 0.1% power, hot and ready. Raise turbine load to bring the reactor to 30% power, and keep the average temperature (Tavg) within 3 °C of its reference (Tref). The reactor follows the turbine, but you\'ll need to withdraw rods and maybe dilute boron to keep Tavg up.',
  tips:['Raise the turbine load target gradually. As steam demand rises, Tavg falls and the reactor\'s power rises to match (negative MTC).','Tref rises as load rises, while Tavg falls. Withdraw the control bank to bring Tavg back up.','If the control bank reaches the top, dilute boron a few ppm at a time. Above 10% you can switch on automatic rod control.'],
  init:function(){var n=1e-3,Pt=n*0.935*3000;return simNew({n:n,sd:1,cb:0.6,load:0,rex:BOL,Tav:292.2+(15+Pt)/300})},failOnTrip:true,
  goals:[['Raise turbine load to at least 30%',function(s){return s.load>=0.295}],['Hold reactor power at 25–35% with |Tavg − Tref| < 3 °C for 60 seconds',function(s,dt,m){m.t=(s.n>=0.25&&s.n<=0.35&&Math.abs(s.Tav-simTref(s))<3)?(m.t||0)+dt:0;return m.t>=60}]]},
 {id:'m3',name:'Mission 3: Xenon after a load cut',brief:'The reactor is at 100% power with equilibrium xenon and automatic rod control on. The grid needs less power: reduce turbine load to 50% and keep running there for 8 hours. Xenon will build up and then burn out, moving the rods. Use boron so the rods don\'t run out of travel. Use 600× speed.',
  tips:['Lower the turbine load target to 50%. Auto rods insert to hold Tavg on program.','Over the next few hours xenon builds up, so the rods withdraw. Dilute boron in small steps to keep the control bank roughly in the middle.','Later xenon falls again: borate so the rods don\'t bottom out.'],
  init:function(){return simNew({n:1,sd:1,cb:0.85,load:1,rex:BOL,xe:true,dhist:true,auto:true})},failOnTrip:true,
  goals:[['Reduce turbine load to 50% (±5%)',function(s){return s.load<=0.55&&s.load>=0.45}],['Run 8 hours at 45–55% power with |Tavg − Tref| < 3 °C (the clock pauses when either is out of range)',function(s,dt,m){if(s.n>=0.45&&s.n<=0.55&&!s.tripped&&Math.abs(s.Tav-simTref(s))<3)m.t=(m.t||0)+dt;return (m.t||0)>=8*3600}],['Finish with |Tavg − Tref| < 3 °C',function(s,dt,m,g){return g[1]&&Math.abs(s.Tav-simTref(s))<3}]]},
 {id:'m4',name:'Mission 4: Race the xenon',brief:'End of fuel cycle: only 10 ppm boron left. Seconds after this mission starts, a feedwater pump fails and the reactor trips from full power. Xenon will start building up. Can you restart before xenon takes away all your spare reactivity? If not, you\'ll have to wait for it to decay: try 3600× speed.',
  tips:['Reset the trip once the rods are fully in, then withdraw the shutdown banks. Power is still falling after the trip, so add reactivity slowly: rushing gives a high startup rate trip.','Withdraw the control bank fully and dilute the remaining boron. Watch the xenon worth growing on the Xenon trend.','If you can\'t reach criticality within about 2 hours, xenon has won. Wait (3600×) for it to peak and decay, roughly a day, then try again.'],
  init:function(){var s=simNew({n:1,sd:1,cb:0.85,load:1,rex:EOL,xe:true,dhist:true,B:10});s.pendingTrip=3;return s},failOnTrip:false,
  goals:[['Reset the reactor trip',function(s){return SIM.ms.wasTripped&&!s.tripped}],['Withdraw the shutdown banks',function(s){return SIM.ms.wasTripped&&s.sd>=0.999}],['Go critical again: with the rods stopped, hold a startup rate of 0.1–1 DPM for 10 s',function(s,dt,m){m.t=(SIM.ms.wasTripped&&!s.tripped&&s.sur>=0.1&&s.sur<=1&&s.rho&&s.rho.tot>0&&simStill(s))?(m.t||0)+dt:0;return m.t>=10}]]},
 {id:'free0',name:'Free play: shut down, fresh core',brief:'No objectives. Explore.',init:function(){return simNew({n:5e-10,sd:0,cb:0,load:0,rex:BOL,B:1200,Tav:292.25})},goals:[]},
 {id:'free1',name:'Free play: 100% power, equilibrium xenon',brief:'No objectives. Try a trip, a load change, or switching auto rods off.',init:function(){return simNew({n:1,sd:1,cb:0.85,load:1,rex:BOL,xe:true,dhist:true,auto:true})},goals:[]},
 {id:'free2',name:'Free play: 100% power, end of cycle',brief:'No objectives. Little boron left: watch what xenon does after a trip.',init:function(){return simNew({n:1,sd:1,cb:0.85,load:1,rex:EOL,xe:true,dhist:true,B:10})},goals:[]}];

